"""Fixed spoken templates. Nothing here is generated by a model, and caller input is never
interpolated into a template (PRD 9.1, 9.3, D-008)."""

from __future__ import annotations

DISCLOSURE = (
    "I'm an automated screening assistant. Who is calling, and what is the purpose of your call?"
)

NEUTRAL_HOLD = "One moment please while I connect you."

# D-008: a fixed statement delivered on an obvious live unsolicited sales call. The user
# chooses a template id; free-form text is deliberately not supported.
REMOVAL_STATEMENTS: dict[str, str] = {
    "standard_v1": (
        "This is an automated message on behalf of the person who owns this number. "
        "They do not accept sales calls. Please add this number to your internal "
        "do-not-call list and stop calling. Goodbye."
    ),
}
DEFAULT_REMOVAL_TEMPLATE = "standard_v1"


def removal_statement(template_id: str) -> str:
    return REMOVAL_STATEMENTS.get(template_id) or REMOVAL_STATEMENTS[DEFAULT_REMOVAL_TEMPLATE]
